const REVIEW_DATE = "2026-07-31";

export const CURRICULUM_TASK_FORMS = Object.freeze([
  "recognise",
  "construct",
  "calculate",
  "transcribe",
  "analyse",
  "perform",
  "describe",
]);

function family(objectiveId, taskForm) {
  return Object.freeze({ objectiveId, taskForm });
}

function objective(spec) {
  return Object.freeze({
    ...spec,
    requiredTaskForms: Object.freeze(spec.requiredTaskForms),
    prerequisiteIds: Object.freeze(spec.prerequisiteIds || []),
    implementations: Object.freeze(spec.implementations || []),
    sourceReference: spec.sourceReference || `written-theory-specification:stage-${spec.stage}`,
    lastReviewed: spec.lastReviewed || REVIEW_DATE,
  });
}

